window.ScripturaLexicons.BDAG_PART_0174 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-01\" data-source=\"BDAG\" data-search=\"Ἱεροσόλυμα topônimo neutro plural ou feminino; forma alternativa indeclinável Jerusalém; cidade histórica; seus habitantes; Jerusalém celestial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἱεροσόλυμα</td><td>topônimo neutro plural ou feminino; forma alternativa indeclinável</td><td>Jerusalém; cidade histórica; seus habitantes; Jerusalém celestial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-02\" data-source=\"BDAG\" data-search=\"Ἱεροσολυμίτης, ου, ὁ substantivo masculino gentílico habitante de Jerusalém; jerosolimitano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἱεροσολυμίτης, ου, ὁ</td><td>substantivo masculino gentílico</td><td>habitante de Jerusalém; jerosolimitano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-03\" data-source=\"BDAG\" data-search=\"ἱεροσυλέω verbo saquear templos; roubar objetos sagrados; cometer sacrilégio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱεροσυλέω</td><td>verbo</td><td>saquear templos; roubar objetos sagrados; cometer sacrilégio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-04\" data-source=\"BDAG\" data-search=\"ἱερόσυλος, ον adjetivo; substantivado masculino ladrão de templo; saqueador de santuário; sacrílego BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερόσυλος, ον</td><td>adjetivo; substantivado masculino</td><td>ladrão de templo; saqueador de santuário; sacrílego</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-05\" data-source=\"BDAG\" data-search=\"ἱερουργέω verbo desempenhar serviço sagrado; exercer uma função sacerdotal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερουργέω</td><td>verbo</td><td>desempenhar serviço sagrado; exercer uma função sacerdotal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-06\" data-source=\"BDAG\" data-search=\"Ἰερουσαλήμ topônimo feminino indeclinável; remissivo Jerusalém; ver Ἱεροσόλυμα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰερουσαλήμ</td><td>topônimo feminino indeclinável; remissivo</td><td>Jerusalém; ver Ἱεροσόλυμα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-07\" data-source=\"BDAG\" data-search=\"Ἱερώνυμος, ου, ὁ nome próprio masculino Jerônimo; procônsul em Éfeso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἱερώνυμος, ου, ὁ</td><td>nome próprio masculino</td><td>Jerônimo; procônsul em Éfeso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-08\" data-source=\"BDAG\" data-search=\"ἱερωσύνη, ης, ἡ substantivo feminino ofício sacerdotal; sacerdócio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερωσύνη, ης, ἡ</td><td>substantivo feminino</td><td>ofício sacerdotal; sacerdócio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-09\" data-source=\"BDAG\" data-search=\"Ἰεσσαί, ὁ nome próprio masculino indeclinável Jessé; pai de Davi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰεσσαί, ὁ</td><td>nome próprio masculino indeclinável</td><td>Jessé; pai de Davi</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-10\" data-source=\"BDAG\" data-search=\"Ἰεφθάε, ὁ nome próprio masculino indeclinável Jefté; juiz de Israel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰεφθάε, ὁ</td><td>nome próprio masculino indeclinável</td><td>Jefté; juiz de Israel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-11\" data-source=\"BDAG\" data-search=\"Ἰεχονίας, ου, ὁ nome próprio masculino Jeconias; rei de Judá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰεχονίας, ου, ὁ</td><td>nome próprio masculino</td><td>Jeconias; rei de Judá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-12\" data-source=\"BDAG\" data-search=\"ιϚ´ sinal numeral grego dezesseis (16) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ιϚ´</td><td>sinal numeral grego</td><td>dezesseis (16)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-13\" data-source=\"BDAG\" data-search=\"Ἰησαί̈ας nome próprio masculino; remissivo Isaías; ver Ἠσαί̈ας BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰησαί̈ας</td><td>nome próprio masculino; remissivo</td><td>Isaías; ver Ἠσαί̈ας</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-14\" data-source=\"BDAG\" data-search=\"Ἰησοῦς nome próprio masculino Josué; Jesus; Jesus Cristo; Jesus Barrabás; Jesus chamado Justo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰησοῦς</td><td>nome próprio masculino</td><td>Josué; Jesus; Jesus Cristo; Jesus Barrabás; Jesus chamado Justo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-15\" data-source=\"BDAG\" data-search=\"ἱκανός, ή, όν adjetivo suficiente; adequado; competente; digno; considerável; numeroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκανός, ή, όν</td><td>adjetivo</td><td>suficiente; adequado; competente; digno; considerável; numeroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-16\" data-source=\"BDAG\" data-search=\"ἱκανότης, ητος, ἡ substantivo feminino capacidade; aptidão; suficiência; qualificação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκανότης, ητος, ἡ</td><td>substantivo feminino</td><td>capacidade; aptidão; suficiência; qualificação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-17\" data-source=\"BDAG\" data-search=\"ἱκανόω verbo tornar suficiente; habilitar; qualificar; capacitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκανόω</td><td>verbo</td><td>tornar suficiente; habilitar; qualificar; capacitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-18\" data-source=\"BDAG\" data-search=\"ἱκανῶς advérbio suficientemente; competentemente; habilmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκανῶς</td><td>advérbio</td><td>suficientemente; competentemente; habilmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-19\" data-source=\"BDAG\" data-search=\"ἱκεσία, ας, ἡ substantivo feminino súplica; oração de um suplicante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκεσία, ας, ἡ</td><td>substantivo feminino</td><td>súplica; oração de um suplicante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0174-20\" data-source=\"BDAG\" data-search=\"ἱκετεύω verbo suplicar; implorar; rogar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱκετεύω</td><td>verbo</td><td>suplicar; implorar; rogar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0174-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἱεροσόλυμα</h1><div class=\"entry-meta\"><span>topônimo neutro plural ou feminino; forma alternativa indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τά</span> e <span class=\"greek\">ἡ</span> (também <span class=\"greek\">Ἰερ</span>-, <span class=\"greek\">Ἱεροσάλημα</span> [GJs 20:4, papiro]) e <span class=\"greek\">Ἰερουσαλήμ</span>, <span class=\"greek\">ἡ</span>, indeclinável (também <span class=\"greek\">Ἱερ</span>-; יְרוּשָׁלַיִם, יְרוּשָׁלֵם): Jerusalém. Sobre a aspiração, ver B-D-F §39, 1; Mlt-H. 101; sobre a forma do nome, B-D-F §56, 1 e 4; W.-S. §10, 3; Mlt-H. 147s.; Ramsay, Exp., 7ª série, 3, 1907, 110ss., 414s.; Harnack, D. Apostelgesch., 1908, 72ss.; R. Schütz, ZNW 11, 1910, 169–87; J. Jeremias, ZNW 65, ’74, 273–76; G. Kilpatrick, NovT 25, ’83, 318–26; D. Sylva, ZNW 74, ’83, 207–21.</p><p class=\"entry-text\">A forma <span class=\"greek\">τὰ</span> <span class=\"greek\">Ἱεροσόλυμα</span> (Políbio 16, 39, 4; Diodoro Sículo 34 + 35, Fgm. 1, 1; 2; 3; 5; Estrabão 16, 2, 34; 36; 40; Apiano, Syr. 50 §252; Cássio Dio 37, 15; 17; Timócares [séc. II a.C.]: 165 Fgm. 1 Jac. [em Eusébio, PE 9, 35]; Pseudo-Hecateu: 264 Fgm. 21, 197 Jac. [em Josefo, C. Ap. 1, 197]; Agatárquides [séc. II a.C.]: 86 Fgm. 20a, 209 Jac. [em Josefo, C. Ap. 1, 209]; Manetão [séc. III a.C.]: 609 Fgm. 10 a, 241 Jac. [em Josefo, C. Ap. 1, 241 e outros]; Lisímaco [séc. I a.C.–I d.C.]: 621 Fgm. 1, 311 Jac. [em Josefo, C. Ap. 1, 311]; PGM 13, 997; LXX nos apócrifos [Thackeray 168]; EpArist 32; 35; 52; Fílon, Leg. ad Gai. 278; Josefo [índice de Niese]; Justino [9 vezes]) é a encontrada em Mateus (a única exceção, 23:37, provém de uma citação), Marcos e João; ocorre também em Lucas e Atos, Gl 1:17s.; 2:1; PtK 4 p. 15, 35.</p><p class=\"entry-text\">A expressão <span class=\"greek\">πᾶσα</span> <span class=\"greek\">Ἱεροσόλυμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:3</a>; GEb 13, 78, parece remontar à forma <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἱεροσόλυμα</span>, <span class=\"greek\">ης</span> (cf. Pel.-Leg. 14, 14 <span class=\"greek\">πᾶσα</span> [<span class=\"greek\">ἡ</span>] <span class=\"greek\">Ἱεροσόλυμα</span>; Tb 14:4; ver B-D-F §56, 4. — Ver também PGM 4, 3069 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καθαρᾷ</span> <span class=\"greek\">Ἱεροσολύμῳ</span> e 13, 233 <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἱερωσολύμῳ</span>).</p><p class=\"entry-text\">A forma <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἰερουσαλήμ</span> (predominante na LXX, pseudoepígrafos, Fílon, Somn. 2, 250; Justino [22 vezes, excluídas citações]; Melitão [de modo constante]. — Josefo, C. Ap. 1, 179 cita Clearco [Fgm. 7] como relatando observações de seu mestre Aristóteles, que empregaria a forma <span class=\"greek\">Ἱερουσαλήμη</span> [questionada por Niese; Eusébio, PE 9, 5, 6 apresenta a mesma citação de Clearco com a forma <span class=\"greek\">Ἱερουσαλήμ</span>]) aparece, além de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a> (ver acima), em Lucas e Atos (ver P.-L. Couchoud/R. Stahl, RHR 97, 1928, 9–17), predomina em Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:22</a>; Apocalipse; 1Cl 41:2; Judaicon 20, 71; GPt; <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἱερουσαλήμ</span>, AcPl Ha 8, 30 (<span class=\"greek\">Ἱεροσόλυμα</span>, BMM, verso 1).</p><p class=\"entry-text\">Na maioria dos casos, o nome vem sem artigo (PsSol; GrBar, prólogo 2; AscIs); ver B-D-F §261, 3; 275, 2; W-S. §18, 5e. Com artigo, somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:23</a>; 5:2; 10:22; 11:18; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:28</a>; Gl 4:25s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:12</a>. Não se podem extrair conclusões seguras da distribuição das duas formas do nome: ambas aparecem num mesmo contexto imediato em Hecateu [264 Fgm. 21 Jac., em Eusébio, PE 9, 4, 2, variante de leitura], e os manuscritos variam consideravelmente.</p><p class=\"entry-text\">① A cidade de Jerusalém: Jerusalém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:1</a> e frequentemente; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:8</a> e frequentemente; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:25</a>, 41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:19</a>, 25s.; Gl 1:17s.; 2:1 e outros. <span class=\"greek\">ἀναβαίνειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἱεροσόλυμα</span>, «subir a Jerusalém», Mt 20:17s.; Mc 10:32s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:13</a>; 5:1; 11:55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:15</a>; 25:1; <span class=\"greek\">Ἰερουσαλήμ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:2</a>; 21:12. <span class=\"greek\">καταβαίνειν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἱεροσολύμων</span>, «descer de Jerusalém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:27</a>; 25:7; <span class=\"greek\">καταβαίνειν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἰερουσαλήμ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:26</a>. <span class=\"greek\">θυγατέρες</span> <span class=\"greek\">Ἰερουσαλήμ</span>, «filhas de Jerusalém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:28</a>, ver <span class=\"greek\">θυγάτηρ</span> 3.</p><p class=\"entry-text\">② Jerusalém usada coletivamente para seus habitantes: Jerusalém, <span class=\"greek\">πᾶσα</span> <span class=\"greek\">Ἱ</span>., «toda a cidade de Jerusalém» (Cecílio de Calacte, Fgm. 75 p. 57, 8, declara que <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἑλλάς</span> [Tucídides 1, 6, 1] equivale a <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἑλλήνων</span>, «os gregos»; Platão, Ep. 7, 348a <span class=\"greek\">πᾶσα</span> <span class=\"greek\">Σικελία</span>; Demóstenes 18, 18; Pselo p. 43, 12 <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Πόλις</span>, «todos os bizantinos»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:3</a>; cf. 3:5; <span class=\"greek\">Ἰερουσαλὴμ</span> <span class=\"greek\">Ἰερουσαλήμ</span>, «Jerusalém, Jerusalém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a> (Ésquines, Ctesiph. 133 <span class=\"greek\">Θῆβαι</span>, <span class=\"greek\">Θῆβαι</span>; Pseudo-Demétrio, Eloc. 267, comenta o texto de Ésquines: «A repetição do nome produz efeito poderoso»; semelhantemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:41</a>; 22:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:4</a>. — H. van der Kwaak, NovT 8, ’66, 56–70); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:38</a>; 13:34 (aqui Jerusalém é apresentada como morta; esse tratamento pessoal é normal no mundo antigo: H. Jahnow, Das hebräische Leichenlied, 1923, 50s.; 100; para o mundo helênico, Il. 18, 333; 19, 287; 315); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:31</a>.</p><p class=\"entry-text\">Para geografia e história, ver H. Guthe, RE VIII 666ss.; XXIII 671s.; H. Vincent e F.-M. Abel, Jérusalem I, 1912; II, 1926; G. Dalman, J. u. s. Gelände, 1930; M. Join-Lambert, Jerusalem (trad. C. Haldane), ’58; P. Winter, ‘Nazareth’ and ‘Jer.’ in Lk 1 and 2, NTS 3, ’56/57, 136–42 (bibliografia); C. Kopp, The Holy Places of the Gospels, ’63 (trad. R. Walls), 283–417. Quanto à história cultural, J. Jeremias, Jerus. in the Time of Jesus (trad. F. H. e C. H. Cave), ’69; B. Lifshitz, Jérusalem sous la domination romaine: ANRW II/8, 77, 444–89; M. Porthuis/C. Safrai (orgs.), The Centrality of Jerusalem, ’96. Quanto ao significado teológico, J. Blinzler, em Festschrift Wikenhauser, ’52, 20–52; J. Schneider, ibid., 207–29. BHHW II 820–50 (bibliografia); OEANE III 224–38.</p><p class=\"entry-text\">③ Jerusalém transcendente, em emprego figurado e escatológico: <span class=\"greek\">ἡ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">Ἰ</span>., «Jerusalém atual», contrapõe-se a <span class=\"greek\">ἄνω</span> <span class=\"greek\">Ἰ</span>., «Jerusalém do alto», a Jerusalém celestial, Gl 4:25s. Para esta última, também <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ἐπουράνιος</span>, «Jerusalém celestial», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:22</a>; e <span class=\"greek\">ἡ</span> <span class=\"greek\">καινὴ</span> <span class=\"greek\">Ἰ</span>., «nova Jerusalém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:12</a>; 21:2; também <span class=\"greek\">ἡ</span> <span class=\"greek\">ἁγία</span> <span class=\"greek\">Ἰ</span>., «santa Jerusalém», 21:10; cf. v. 2. Sobre o emprego teológico, ver J. de Young, Jerus. in the NT, ’60; bibliografia também em <span class=\"greek\">πόλις</span> 2. — M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἱεροσολυμίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Também -<span class=\"greek\">είτης</span>, <span class=\"greek\">Ἰεροσολυμίτης</span>, <span class=\"greek\">Ἰεροσολυμείτης</span>; Sir 50:27; 4Mc 4:22; 18:5; Josefo [índice de Niese].) Habitante de Jerusalém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:25</a>. — TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱεροσυλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἱερός</span>, <span class=\"greek\">συλάω</span> e verbete seguinte; sobre a formação da terminação, ver DELG, s.v. <span class=\"greek\">συλάω</span>; Aristófanes e posteriores; Políbio 30, 26, 9; Artemidoro 3, 3; Heráclito, Ep. 7, 4 H.; SIG 417, 8; 10 [273/272 a.C.; cf. <span class=\"greek\">ἱεροσυλία</span> 1017, 18; em histórias de Alexandre: PSI II, 1285 col. I, 38; col. III, 42; col. IV, 9 [séc. II d.C.]; 2Mc 13:6; <span class=\"greek\">ἱεροσύλημα</span> 4:39; <span class=\"greek\">ἱερόσυλος</span> 4:42]; 2Mc 9:2; Fílon; Josefo, C. Ap. 1, 249; Ant. 17, 163.)</p><p class=\"entry-text\">① Retirar objetos de um templo por força ou às escondidas: roubar ou saquear templos (Manetão: 609 Fgm. 10a, 249 Jac. [= Josefo, C. Ap. 1, 249], com vandalismo contra imagens sagradas). Provavelmente deve ser entendido literalmente como saque de templo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:22</a> (junto de <span class=\"greek\">κλέπτω</span> e <span class=\"greek\">μοιχεύω</span>, como Fílon, Conf. Lingu. 163; cf. também Herm. Wr. 12, 5; J. Derrett, NTS 40, ’94, 558–71, com ênfase na violação da consciência). Alguns interpretam <span class=\"greek\">ἱ</span>., nessa passagem, como:</p><p class=\"entry-text\">② Praticar atos irreverentes: cometer sacrilégio (em Iseu 8, 39, <span class=\"greek\">ἱεροσυλία</span> se emprega quanto a comportamentos relacionados aos ritos funerários). — E. Krentz, The Name of God in Disrepute—Romans 2:17–29: CTM 17, ’90, 429–39. — DELG, s.v. <span class=\"greek\">συλάω</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερόσυλος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivado masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete anterior; Aristófanes e posteriores; Aristóteles, Pol. 5, 4 p. 1304a, 3s.; Diodoro Sículo 16, 25, 2; Plutarco, Sol. 17, 1; inscrições; 2Mc 4:42; Josefo, Bell. 1, 654; Ant. 16, 164.)</p><p class=\"entry-text\">① Referente a quem rouba um templo: substantivado, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱ</span>., «ladrão de templo» (Drácon, em Plutarco, Solon 17, 2; Díon Crisóstomo 31 [14], 82; Alcífron 3, 7, 5; Fílon, De Jos. 84; Josefo, Ant. 16, 168), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:37</a>. Alguns (por exemplo, K. Latte, Hlg. Recht, 1920, 83ss.) interpretam <span class=\"greek\">ἱ</span>., nessa passagem, como:</p><p class=\"entry-text\">② Relativo ao sacrilégio; sentido transferido de 1: substantivado, «pessoa sacrílega», equivalente a saqueador de templo (SIG 578, 47ss. [séc. II a.C.] <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">εἴπας</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πρήξας</span> <span class=\"greek\">τι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τόνδε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> … <span class=\"greek\">ἔστω</span> <span class=\"greek\">ἱερόσυλος</span>; 1016, 8; SIG2 680, 10. Ver também Menandro, Dyscolus 640 <span class=\"greek\">ἱερόσυλε</span> <span class=\"greek\">σύ</span>, «seu patife!»; Epitr. 1100 S. [= 742 Kö.]). — DELG, s.v. <span class=\"greek\">συλάω</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερουργέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(De <span class=\"greek\">ἱερουργός</span>, «sacerdote que oferece sacrifícios»; Plutarco, Num. 14, 1; Alex. 31, 4; Herodiano 5, 6, 1; 5, 5, 9; Filóstrato, Vi. Soph. 2, 10, 2 p. 91, 25; CIG, adendo a 4528 [III p. 1175]; IG2 I, 4, 4s.; 8 [séc. V a.C.]; 4Mc 7:8, variante de leitura; Fílon, Mos. 1, 87 e outros; Josefo, Ant. 6, 102; 7, 333.) Atuar em alguma função cultual ou sagrada: prestar serviço sagrado, exercer a função de sacerdote. Construído com acusativo <span class=\"greek\">τὶ</span>, «em relação a alguma coisa»: <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, «servir sacerdotalmente ao evangelho» (talvez com ênfase no sacrifício; Field, Notes 165), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:16</a>. — DELG, s.v. <span class=\"greek\">ἱερός</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰερουσαλήμ</h1><div class=\"entry-meta\"><span>topônimo feminino indeclinável; remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Ver <span class=\"greek\">Ἱεροσόλυμα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἱερώνυμος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Heródoto 9:33, 2; Josefo.) Jerônimo, procônsul em Éfeso, AcPl Ha 1, 30; 33; 2, 9; 12; 3, 1; 4; 4, 5; 8; 16; 5, 4; 10; 22.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερωσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Função sacerdotal, sacerdócio (ver <span class=\"greek\">ἱερός</span>; Heródoto e posteriores; Platão, Demóstenes; Diodoro Sículo 5, 58, 2; Plutarco e outros; inscrições; PBrem 70, 6; LXX; Test12Patr; Fílon; Josefo, Ant. 2, 216; C. Ap. 1, 31; Atenágoras 28, 3. Quanto à formação da palavra, ver Mayser 15; 154, 11 [bibliografia]; Mlt-H. 358), 1Cl 43:2. <span class=\"greek\">ἡ</span> <span class=\"greek\">Λευιτικὴ</span> <span class=\"greek\">ἱ</span>., «o sacerdócio levítico», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a>; <span class=\"greek\">μετατιθεμένης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἱ</span>., «mudando-se o sacerdócio», v. 12; <span class=\"greek\">ἀπαράβατον</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἱ</span>., «possuir o sacerdócio intransmissível», v. 24 (Pseudo-Aristóteles, Mirabilia 137 <span class=\"greek\">τ</span>. <span class=\"greek\">ἱερωσύνην</span> <span class=\"greek\">ἔχειν</span>, «ocupar o ofício sacerdotal»). — DELG, s.v. <span class=\"greek\">ἱερός</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰεσσαί, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Indeclinável (יִשַׁי; em Josefo, <span class=\"greek\">Ἰεσσαῖος</span>, <span class=\"greek\">ου</span> [Ant. 6, 162]; Justino). Jessé, pai de Davi (1Km 16:1, 10; 17:12; 20:27; TestSol 26:9 H), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:22</a>; 1Cl 18:1. Na genealogia de Jesus (cf. Rt 4:22), Mt 1:5s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:32</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span>., «o rebento de Jessé», referente ao rei messiânico, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:12</a> (Is 11:10).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰεφθάε, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Indeclinável (יִפְתָּח; em Josefo, <span class=\"greek\">Ἰαφθᾶς</span> [variante <span class=\"greek\">Ἰεφθάς</span>], <span class=\"greek\">α</span> [Ant. 5, 271]). Jefté, filho de Gileade, um dos juízes de Israel (Jz 11s.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:32</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰεχονίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(יְהוֹיָכִין = יְכָנְיָהוּ.) Jeconias, rei de Judá (Josefo, Bell. 6, 103; Ant. 10, 229s.). Segundo a genealogia de Mt 1:11s., era filho de Josias e tinha irmãos. Em 1Cr 3:15s., <span class=\"greek\">Ἰεχονία</span> é filho de <span class=\"greek\">Ἰωακίμ</span> e neto de Josias, e menciona-se somente um irmão. 1Cr 3:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:12</a> e Lc 3:23ss., Códice D, concordam em que ele era pai de Salatiel.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ιϚ´</h1><div class=\"entry-meta\"><span>sinal numeral grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Numeral 16, GJs 12:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰησαί̈ας</h1><div class=\"entry-meta\"><span>nome próprio masculino; remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Ver <span class=\"greek\">Ἠσαί̈ας</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰησοῦς</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(יֵשׁוּעַ, Jesua, forma posterior de יְהוֹשׁוּעַ, Josué; ver M. Lidzbarski, Handb. d. nordsem. Epigr., 1898, 291; F. Praetorius, ZDMG 59, 1905, 341s.; F. Steinmetzer, BZ 14, 1917, 193ss.; F. Waele, Wetenschappelijke Tijdingen 5, ’42, 177–81.) Genitivo <span class=\"greek\">οῦ</span>, dativo <span class=\"greek\">οῦ</span>, acusativo <span class=\"greek\">οῦν</span>, vocativo <span class=\"greek\">οῦ</span>, artigo <span class=\"greek\">ὁ</span>: Josué/Jesus. O nome, comum entre os judeus (várias pessoas assim denominadas na LXX e em Josefo [índice de Niese]; EpArist 48; 49; inscrição do tempo de Augusto [RevÉpigr, nova série, 1, 1913, n.º 12]; POxy 816 [séc. I a.C.]; PLond III, 1119a, 2 p. 25 [105 d.C.]; óstracos Sb 5812; 5817; 5820; 5822), costuma aparecer com artigo nos Evangelhos (em João, o nominativo ocorre frequentemente sem artigo: R. Nevius, NTS 12, ’65, 81–85; G. Fee, NTS 17, ’71, 168–83), exceto quando acompanhado de termo em aposição com artigo; nas epístolas e no Apocalipse, não leva artigo regularmente (B-D-F §260, 1; W-S. §18, 6; H. von Soden, D. Schriften des NTs I/2, 1911, 1406–9).</p><p class=\"entry-text\">① Josué, sucessor de Moisés, comandante militar do povo ao ingressar em Canaã (livro de Josué; 1Mc 2:55; 2Mc 12:15; Fílon, Josefo, Justino; Melitão, HE 4, 26, 14; SibOr 2, 247), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.45\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:8</a>. Na forma plena <span class=\"greek\">Ἰ</span>. <span class=\"greek\">υἱὸς</span> <span class=\"greek\">Ναυή</span>, «Josué, filho de Num» (Js 1:1; cf. Sir 46:1; AssMos, fragmento f; Justino, D. 113, 2; 115, 4), B 12:8s.; ou <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ναυή</span>, 1Cl 12:2 (AssMos, fragmento a; Justino, D. 49, 6 e outros; cf. 111, 4 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ναυῆ</span>).</p><p class=\"entry-text\">② Jesus, filho de Eliezer, na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:29</a> (variante <span class=\"greek\">Ἰωσή</span>).</p><p class=\"entry-text\">③ Jesus Cristo, designado mais precisamente por <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χριστός</span>, <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰ</span>., <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">Ἰ</span>. (<span class=\"greek\">Χριστός</span> [assim também TestSol D 1, 12]), <span class=\"greek\">ὁ</span> <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χριστός</span> e outras expressões, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:1</a>, 21, 25 e frequentemente. Ver <span class=\"greek\">Χριστός</span>, <span class=\"greek\">κύριος</span>, <span class=\"greek\">σωτήρ</span>. Sobre o emprego dos nomes em Paulo, ver E. von Dobschütz, D. Th.-Briefe, em Meyer7, 1909, 60s. — Duas ocorrências em Aristides (15, 1; 3), 5 vezes em Melitão e frequentes em Justino. — Sobre as abreviações dos nomes nos manuscritos, ver L. Traube, Nomina sacra, 1907, 113ss.; E. Nestle, ZNW 9, 1908, 248ss.</p><p class=\"entry-text\">Bibliografia mais antiga acerca de Jesus: A. Schweitzer, Gesch. der Leben-Jesu-Forschung2, 1913. Outras referências: RGG III3, ’59, 619–53 (bibliografia 651–53); M. Veit, D. Auffassung v. d. Pers. Jesu im Urchristent. nach d. neuesten Forschungen, tese, Marburg ’46; R. Eisler, <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">βασιλεύς</span>, 1928–1930; R. Bultmann, Jesus2, 1929 (reimpresso em ’51), D. Urchristentum, ’49; P. Feine, Jesus, 1930; F. Prat, Jésus-Christ, ’33; J. Klausner, J. von Nazareth2, ’34 (trad. inglesa 1926); M. Goguel, La Vie de J., ’32 (trad. inglesa ’44); K. Adam, Jes. Christus4, ’35; F. Willam, D. Leben J. im Lande u. Volke Israel4, ’34; J. Pickl, Messiaskönig J. in d. Auffassung seiner Zeitgenossen3, ’39; R. Guardini, D. Herr, ’37; M. Dibelius, Jesus, ’39 (3’60), trad. inglesa ’49; A. Loisy, Hist. et mythe à propos de J-Ch., ’38;</p><p class=\"entry-text\">H. Felder, Jes. v. Naz.2, ’39; C. Noel, The Life of J., ’39; V. Grÿnbech, J. d. Menschensohn, ’41; R. Meyer, D. Proph. aus Galil., ’40; C. Cadoux, The Hist. Mission of J., ’41; A. Olmstead, J. in the Light of History, ’42; W. Manson, J. the Messiah, ’43, 6ª impressão ’52; A. Rawlinson, Christ in the Gospels, ’44; G. Ricciotti, Life of Christ, ’47; F. Büchsel, Jesus, ’47; H. Cadbury, J.: What Manner of Man, ’47; G. Duncan, J., Son of Man, ’47; J. Hoffmann, Les Vies de Jésus et le Jésus de l’Histoire, ’47; W. Kümmel, Verheissung u. Erfüllung2, ’53; G. Bornkamm, J. von Nazareth, ’56 (trad. inglesa ’60); J. Knox, Jesus, Lord and Christ, ’58; H. Ristow e K. Matthiae (orgs.), D. historische Jesus u. d. kerygmatische Christus, ’60;</p><p class=\"entry-text\">E. Schweizer, Jesus (trad. inglesa D. Green), ’71; H. Braun, Qumran u. d. NT II, ’66, 54–118 (bibliografia); W. Kümmel, em TRu 31, ’65/66; 40, ’75; 41, ’76 e outros; G. Schneider, EDNT II 180–84; J. Meier, A Marginal Jew—Rethinking the Historical Jesus, 2 volumes, ’91–’94 (bibliografia). Para estudos posteriores, consultar instrumentos bibliográficos especializados. Quanto ao nome: W. Lowrie, Theol. Today 8, ’51, 11–19; V. Taylor, Names of Jesus, ’53.</p><p class=\"entry-text\">④ Jesus Barrabás, Mt 27:16s.; ver <span class=\"greek\">Βαραββᾶς</span>.</p><p class=\"entry-text\">⑤ Jesus/Justo: <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λεγόμενος</span> <span class=\"greek\">Ἰοῦστος</span>, «Jesus, chamado Justo» (sobre o nome duplo, ver Dssm., B 183s. [BS 315]), <span class=\"greek\">συνεργὸς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">περιτομῆς</span>, «cooperador proveniente da circuncisão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4:11</a>. Conjecturou-se (Zahn, Einl. I 321, 4; E. Amling, ZNW 10, 1909, 261s.) que esse Jesus seja novamente referido em Fm 23. A respeito, A. Deissmann, D. Name J.: Mysterium Christi, ’31, 13–41. — M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os três verbetes seguintes; autores trágicos, Heródoto e posteriores; inscrições, papiros, LXX; PsSol 5:17; TestNapht 2:4; JosAs 28:11; ParJer 6:6 [שַׁדַּי]; ApcSed 2:3; EpArist, Fílon, Josefo, Justino; Taciano 36, 2 <span class=\"greek\">ἱκανώτατος</span>; empréstimo no hebraico rabínico.)</p><p class=\"entry-text\">① Suficiente em grau: suficiente, adequado, bastante grande. <span class=\"greek\">ἱκανόν</span> <span class=\"greek\">ἐστιν</span>, «é suficiente» (Epicteto 1, 2, 36; 3Km 16:31; a cópula frequentemente se omite: Gn 30:15; Ez 34:18; Justino, D. 13, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:38</a> (W. Western, ET 52, ’40/41, 357: «grande» ou «bastante longo»). <span class=\"greek\">εἴ</span> <span class=\"greek\">τινι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δοκοίη</span> <span class=\"greek\">κἂν</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἱκανά</span>, «se até essas coisas parecessem insuficientes a alguém», Dg 2:10.</p><p class=\"entry-text\">O latinismo (B-D-F §5, 3b; Mlt. 20s.) <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινι</span>, latim satisfacere alicui, «satisfazer alguém» (Políbio 32, 3, 13; Apiano, Lib. 74; BGU 1141, 13 [14 a.C.] <span class=\"greek\">ἐάν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">Ἔρως</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ποιήσῃ</span> <span class=\"greek\">γράψον</span> <span class=\"greek\">μοι</span>; POxy 293, 10; PGiss 40 I, 5); também possível: «fazer um favor a alguém» (assim claramente Diógenes Laércio 4, 50, «atender a um pedido»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:15</a> (cf. <span class=\"greek\">χαρίζομαι</span>, PFlor I, 61, 61 [85 d.C.] = Mitt-Wilck. II/2, 80 II, 61, de alguém «merecedor de açoites»: <span class=\"greek\">ἄξιος</span> … <span class=\"greek\">μαστιγωθῆναι</span>, linhas 59s.); Hs 6, 5, 5. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «caução, garantia, fiança» (POxy 294, 23 [22 d.C.]; BGU 530, 38; PStras 41, 51); <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., latim satis accipere, «receber fiança» (OGI 484, 50; 629, 101 [ambos do séc. II d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:9</a>.</p><p class=\"entry-text\">② Correspondente a um padrão: apto, apropriado, competente, qualificado, capaz, com a conotação «digno», «suficientemente bom» (Tucídides; Diodoro Sículo 13, 106, 10; POxy 1672, 15; Êx 4:10). <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span>, «apto para alguma coisa» (Platão, Prot. 322b; 2Mc 10:19; EpArist 211), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:16</a> (F. Fallon, HTR 76, ’83, 369–74, motivo do «homem divino»).</p><p class=\"entry-text\">Seguido de infinitivo (Heródoto 8, 36; Josefo, Ant. 1, 29; 5, 51; Justino, D. 8, 2; B-D-F §393, 4; Rob. 658): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:5</a> (Dodd 15s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:2</a> (Josefo, Ant. 3, 49 <span class=\"greek\">εἰπεῖν</span> <span class=\"greek\">ἱ</span>., «capaz de falar»); 1Cl 50:2. Também seguido de <span class=\"greek\">ἵνα</span> (B-D-F §393, 4; Rob. 658; cf. PHolm 4, 23): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:27</a>, variante de leitura. — Ver ITr 3:3, conjectura de Lightfoot.</p><p class=\"entry-text\">③ De extensão ou grau considerável: grande, considerável.</p><p class=\"entry-text\">ⓐ De pessoas: <span class=\"greek\">ὄχλος</span>, «grande multidão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:24</a>, 26; 19:26 (SIG 569, 14 <span class=\"greek\">πλῆθος</span> <span class=\"greek\">ἱ</span>.; PPetr II, 20; II, 7; PLille 3, 76 [séc. III a.C.]; Josefo, Ant. 5, 250). <span class=\"greek\">λαὸν</span> <span class=\"greek\">ἱ</span>., «grande número de seguidores», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:37</a>, variante de leitura.</p><p class=\"entry-text\">ⓑ De coisas: <span class=\"greek\">κλαυθμός</span>, «grande pranto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:37</a> (= houve muito choro). <span class=\"greek\">φῶς</span>, «luz muito brilhante», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:6</a>. — <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ἡ</span>. <span class=\"greek\">ἐπιτιμία</span>, «a punição é bastante severa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:6</a> (sobre a falta de concordância de gênero, ver B-D-F §131; Rob. 411). — <span class=\"greek\">ἀργύρια</span>, «quantia de dinheiro bastante elevada» (literalmente «suficiente», isto é, «suborno substancial», REB), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:12</a> (cf. SIG 1106, 74; 77).</p><p class=\"entry-text\">Especialmente em expressões de tempo: <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἱκανοῦ</span>, «por muito tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:8</a>, variante de leitura. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἱκανόν</span>, «suficientemente», «por quanto tempo se quiser», «por longo tempo» (Políbio 11, 25, 1; Diodoro Sículo 11, 40, 3; 13, 100, 1; SIG 685, 34; 2Mc 7:5; 8:25; EpArist 109), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:11</a>. <span class=\"greek\">ἱ</span>. <span class=\"greek\">χρόνος</span>, «tempo considerável» (Aristófanes; Platão, Leg. 5 p. 736c; SIG 665, 12; UPZ 161, 29 [119 a.C.] <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἱ</span>. <span class=\"greek\">χρόνον</span>; Josefo, Ant. 7, 22; C. Ap. 1, 237); <span class=\"greek\">ἱ</span>. <span class=\"greek\">χρόνον</span> <span class=\"greek\">διέτριψαν</span>, «permaneceram bastante tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:3</a> (Justino, D. 2, 3). <span class=\"greek\">ἱ</span>. <span class=\"greek\">χρόνου</span> <span class=\"greek\">διαγενομένου</span>, «depois de transcorrido bastante tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:9</a>. <span class=\"greek\">ἱκανῷ</span> <span class=\"greek\">χρόνῳ</span>, «por longo tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:11</a> (sobre o dativo, ver B-D-F §201; Rob. 527). No plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:9</a> (B-D-F §201; Rob. 470). <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">χρόνων</span>, «há muito tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:8</a>; <span class=\"greek\">ἐκ</span> <span class=\"greek\">χρόνων</span> <span class=\"greek\">ἱ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:27</a>, variante de leitura; em lugar desta, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">χρόνων</span> <span class=\"greek\">ἱ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:27</a>, Códice D. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">χρόνον</span>, Qua.</p><p class=\"entry-text\">④ Em números relativamente elevados: muitos, não poucos.</p><p class=\"entry-text\">ⓐ De pessoas, emprego absoluto: <span class=\"greek\">ἱκανοί</span>, «muitos, não poucos» (Mitt-Wilck. I/2, 11 B Fr. (a), 10 [123 a.C.]; PTebt 41, 13 <span class=\"greek\">ἱκανῶν</span> <span class=\"greek\">ἡμῶν</span>; 1Mc 13:49; Josefo, Ant. 14, 231), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:12</a>; 14:21; 19:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:30</a> («bastantes», em contraste com <span class=\"greek\">πολλοί</span>, como em At 19:18s.); cf. <span class=\"greek\">μαθηταί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:11</a>, variante de leitura.</p><p class=\"entry-text\">ⓑ De coisas: <span class=\"greek\">λαμπάδες</span>, «muitas lâmpadas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:8</a>. <span class=\"greek\">ἀγέλη</span> <span class=\"greek\">χοίρων</span> <span class=\"greek\">ἱκανῶν</span>, «grande manada de porcos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:32</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">ἱ</span>., «com muitas palavras», isto é, «longamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:9</a>. No superlativo: <span class=\"greek\">κεράμια</span> <span class=\"greek\">ἱκανώτατα</span>, «grande quantidade de vasos», Hm 12, 5, 3 (SIG 736, 108 <span class=\"greek\">ξύλα</span> <span class=\"greek\">ἱ</span>.).</p><p class=\"entry-text\">ⓒ De períodos de tempo: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἐτῶν</span>, «por muitos anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:23</a>, variante (cf. 2Mc 1:20). <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ἱ</span>. (UPZ 162 II, 15 [117 a.C.] <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἱκανὰς</span> <span class=\"greek\">ἡμέρας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:23</a>; <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἱ</span>., «por muitos dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:43</a>; 18:18. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἡμέραις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:7</a>. — B. 927; DELG, s.v. <span class=\"greek\">ἵκω</span>; M-M; TW; Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Estado de quem está qualificado ou é adequado para alguma coisa: aptidão, capacidade, qualificação, suficiência (ver <span class=\"greek\">ἱκανός</span>; Lísias, Fgm. 211 Sauppe [em Pólux 4, 23]; Platão, Lysis 11 p. 215a; estoicos III 68, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:5</a>. — DELG, s.v. <span class=\"greek\">ἵκω</span>; TW; Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἱκανός</span>.) 1º aoristo <span class=\"greek\">ἱκάνωσα</span>; imperativo de 2ª pessoa do singular <span class=\"greek\">ἱκάνωσον</span> («contenta-te com», PsSol 2:22); passivo <span class=\"greek\">ἱκανώθην</span>, LXX (fora do NT, usa-se a passiva: Teles p. 39, 6; 42, 4; Dionísio de Halicarnasso 2, 74; PTebt 20, 8; LXX [principalmente imperativo presente na 3ª pessoa singular <span class=\"greek\">ἱκανούσθω</span>, «que seja suficiente»]; TestIss 1:7; ver Anz 353). Fazer alguém adequar-se a um padrão: tornar suficiente, habilitar, qualificar (talvez aproximando-se do sentido «conferir poderes», «autorizar» [PTebt 20, 8]). Com duplo acusativo: «qualificar alguém para alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:6</a>. Construção <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, «alguém para alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:12</a> (ver <span class=\"greek\">καλέω</span> 4). — DELG, s.v. <span class=\"greek\">ἵκω</span>; M-M; TW; Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Advérbio de <span class=\"greek\">ἱκανός</span> (Sófocles, Heródoto e posteriores; PPetr III, 53n, 3; POxy 1088, 56; PTebt 411, 6; Jó 9:31; 3Mc 1:4; Fílon, Op. M. 90; Josefo, C. Ap. 1, 58; 287; Ant. 2, 31; Justino; Atenágoras 10, 1).</p><p class=\"entry-text\">① Suficientemente, quanto à quantidade: <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἐπεστείλαμεν</span>, «escrevemos suficientemente», 1Cl 62:1.</p><p class=\"entry-text\">② Com competência, habilmente: <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἐλέγχειν</span>, «refutar com habilidade», Epil Mosq 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os três verbetes seguintes; Eurípides e posteriores; inscrições, papiros; 2Mc 10:25; 12:42; TestSol 22:5; ApcMos 13; Fílon; Josefo, Ant. 11, 326; 12, 300; Justino, D. 107, 2.) Oração de quem suplica: súplica; <span class=\"greek\">ἱ</span>. <span class=\"greek\">ποιεῖσθαι</span>, «fazer uma súplica» (Ésquines 3, 121; Dionísio de Halicarnasso 8, 43, 5); <span class=\"greek\">ἐκτενῆ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δέησιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ποιεῖσθαι</span>, «orar com súplica ardente», 1Cl 59:2 (<span class=\"greek\">ἱ</span>. com <span class=\"greek\">δέησις</span>, como em OGI 569, 11; Mitt-Wilck. I/2, 6, 3). — DELG, s.v. <span class=\"greek\">ἵκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0174-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">ἱκέτευσα</span>, LXX (ver verbete anterior e os dois seguintes; Homero e posteriores; inscrições, papiros, LXX; Josefo, C. Ap. 2, 213). Suplicar, implorar; com acusativo <span class=\"greek\">θεόν</span>, «Deus» (maldição de Artemísia [papiro em Sb 5103, séc. III a.C.], 9s. <span class=\"greek\">ἱκετεύουσα</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span>; Apiano, Bell. Civ. 2, 104 §431 <span class=\"greek\">θεοὺς</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Καῖσαρ</span> <span class=\"greek\">ἱκέτευεν</span>; Sl 36:7; 2Mc 11:6; <span class=\"greek\">σοὶ</span> <span class=\"greek\">ὅπως</span>, TestSol 13:7 C; TestAbr; EpArist 197; Fílon, Cherub. 47; Josefo, Ant. 3, 6), 1Cl 7:7; 48:1. Seguido de infinitivo, 2:3. Variante <span class=\"greek\">ἱκέτευεν</span> por <span class=\"greek\">ἐκάθισεν</span> … <span class=\"greek\">ἐλιτάνευσεν</span>, GJs 2:4 (códice E). — Schmidt, Syn. I 177–98; DELG, s.v. <span class=\"greek\">ἵκω</span>.</p></section></article>\n"};
